+package com.example;
+
+import static org.junit.jupiter.api.Assertions.*;
+
+import org.junit.jupiter.api.Test;
+import org.springframework.boot.test.context.SpringBootTest;
+
+import com.example.contact.*;
+import com.vaadin.browserless.SpringBrowserlessTest;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.textfield.*;
+
+@SpringBootTest
+class ContactViewTest extends SpringBrowserlessTest {
+
+    @Test
+    void flow() {
+        navigate("contact", ContactView.class);
+        test($(Button.class).withText("Send").single()).click();
+        assertEquals("Name is required", $(TextField.class).withCaption("Name").single().getErrorMessage());
+        test($(TextField.class).withCaption("Name").single()).setValue("A");
+        test($(EmailField.class).single()).setValue("a@b.co");
+        test($(TextArea.class).single()).setValue("hi");
+        test($(Button.class).withText("Send").single()).click();
+        assertFalse($(Button.class).withText("Send").single().isEnabled());
+        test($(TextField.class).withCaption("Name").single()).setValue("B");
+        assertTrue($(Button.class).withText("Send").single().isEnabled());
+        com.vaadin.flow.component.UI.getCurrent().navigate("about");
+        assertEquals(1, $(Dialog.class).all().size());
+        test($(Button.class).withText("Discard").single()).click();
+        assertEquals("About", $(H1.class).single().getText());
+    }
+}
